```cpp
#include <iostream>
#include <map>

int main()
{
    int number;
    std::cout << "Enter a number: ";
    std::cin >> number;

    std::map<int, int> factors;

    for (int i = 1; i <= number; ++i)
    {
        if (number % i == 0)
        {
            factors[i]++;
        }
    }

    int sum_of_factors = 0;
    for (const auto& factor : factors)
    {
